const cats=[{name:'奶油',quote:'照片就够了，我会陪你慢慢补上故事。',trait:'温柔的日常陪伴家',threshold:0},{name:'橘子',quote:'又收集到了小美好？让我看看！',trait:'快乐的美食探险家',threshold:3},{name:'墨墨',quote:'安静地待一会儿，也很好。',trait:'安静的夜晚守护者',threshold:8},{name:'栗栗',quote:'今天又发现了什么新鲜事？',trait:'好奇的生活收藏家',threshold:15},{name:'糯米',quote:'看到你回来，我就很开心。',trait:'害羞的暖心小伙伴',threshold:25}];
