const moods=['小确幸','开心','平静','有点累'],tones={auto:'自动柔和',warm:'奶油暖调',fresh:'清新通透',original:'保留原色'};
const decor=[{text:'☕',words:['咖啡','早餐','下午茶','coffee','cafe','美食'],label:'咖啡时光'},{text:'✈',words:['旅行','旅游','出发','飞机','旅途','travel','trip'],label:'出发去旅行'},{text:'☀',words:['阳光','太阳','晴天','散步','sun'],label:'阳光刚好'},{text:'♡',words:['开心','喜欢','幸福','朋友','快乐','爱','happy'],label:'一点小快乐'},{text:'✎',words:['上学','作业','考试','课堂','学习','school','study'],label:'学习日记'},{text:'✧',words:['上班','工作','下班','加班','work'],label:'下班快乐'},{text:'☾',words:['夜晚','晚安','睡觉','月亮','night'],label:'晚安啦'}];
decor.push({text:'❀',words:['花','花园','春天','flower'],label:'小花开了'},{text:'♧',words:['植物','仙人掌','窗边','plant'],label:'窗边植物'});
const stampIndex=text=>({'☕':0,'✈':1,'☀':2,'♡':3,'✎':4,'✧':5,'☾':6,'❀':7,'♧':8})[text];
