document.addEventListener('submit',async e=>{if(!['book-form','rename-book-form','profile-form','cat-name-form'].includes(e.target.id))return;e.preventDefault();const form=e.target,values=Object.fromEntries(new FormData(form)),button=form.querySelector('button');button.disabled=true;try{if(form.id==='cat-name-form'){const name=values.name.trim();if(!name||Array.from(name).length>12)throw new Error('名字请写 1—12 个字。');cats[state.cat].name=name;state.catNames[state.cat]=name;persist();}else if(form.id==='rename-book-form'){const b=state.books.find(b=>b.id===form.dataset.book),title=values.title.trim();if(!title)throw new Error('给本子起个名字吧。');if(!b.local)await write('/api/notebooks/'+b.id,'PATCH',{title});b.title=title;persist();}else if(form.id==='book-form'){if(state.books.length>=notebookLimit(photosCount()))throw new Error('本子已满，解锁第四、第五只猫咪会增加名额。');const b={id:uuid(),title:values.title.trim(),color:state.books.length%6,local:true};if(state.profile){await write('/api/notebooks','POST',b);delete b.local;}state.books.push(b);state.activeBook=b.id;persist();}else state.profile=(await write('/api/profile','PATCH',values)).profile;closeModal();render();}catch(e){toast(e.message);button.disabled=false;}});
