$('#modal').addEventListener('cancel',e=>{if(state.starterCat===null){e.preventDefault();return;}if(importing){e.preventDefault();importing.stop=true;toast('当前照片完成后停止。');}});
function migrate(r){const a={id:uuid(),src:r.image,label:'生活照片',tags:'',ratio:1,sample:!!r.sample||r.image.includes('coffee.png'),hash:r.id,original:r.original};if(a.sample)a.src='/assets/coffee.webp';const items=[{...photoItem(a),x:r.x??13,y:r.y??33,w:r.size??74,rotation:r.rotation??-7}];if(r.showCat)items.push({id:uuid(),type:'cat',cat:0,x:61,y:61,w:28,rotation:0});return {id:r.recordId||r.id,bookId:state.books[0].id,title:r.title||'今天的小美好',date:r.date||today,cat:0,library:[a],pages:[{id:uuid(),template:r.template||0,title:'',caption:r.caption||'',mood:r.mood||'小确幸',items}]};}
async function boot(){try{const all=await local('getAll'),saved=all.find(r=>r.id==='v2-state');if(saved){for(const k of ['books','records','draft','cat','credits','lastActivity','catLife','catNames','starterCat','activeBook','deletedBooks'])if(saved[k]!==undefined)state[k]=saved[k];if(!state.books.length&&!state.deletedBooks.length)state.books=defaults();if(state.starterCat===null&&((saved.records||[]).length||saved.lastActivity||Object.keys(saved.catLife||{}).length))state.starterCat=0;}else{for(const r of all.filter(r=>r.id!=='draft'&&r.image))state.records.push(migrate(r));const oldDraft=all.find(r=>r.id==='draft'&&r.image);if(oldDraft)state.draft=migrate(oldDraft);persist();}}catch{toast('本机存储不可用，请登录同步或及时导出。');}if(!unlocked(state.cat))state.cat=state.starterCat??0;render();await reconnect();for(const [i,name]of Object.entries(state.catNames))if(cats[i])cats[i].name=name;if(state.starterCat===null){render();await firstBackground();chooseStarter();}else{refreshLife();render();firstIntro(latestStory(state.catLife,cats));}refreshExistingBorders();}
boot();
if(document.modelContext?.registerTool){Promise.resolve(document.modelContext.registerTool({name:'get_journal_overview',title:'查看手账概况',description:'读取当前用户可见的本子数量、手账数量和猫咪成长，不返回私密照片或文字。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('此工具不接受参数');return {notebooks:state.books.length,entries:state.records.length,photos:photosCount(),unlockedCats:cats.filter((c,i)=>unlocked(i)).map(c=>c.name),currentView:state.view};}})).catch(()=>{});}

document.addEventListener('visibilitychange',()=>{if(!document.hidden&&state.view==='cats')render();});

function chooseStarter(){openModal('<h2>领养第一只小猫</h2><p>选一位伙伴开始记录，其余小猫会慢慢到来。</p><div class="starter-picker">'+cats.map((c,i)=>'<button data-action="starter-pick" data-cat="'+i+'">'+catSprite(i)+'<strong>'+esc(c.name)+'</strong><small>'+catTraits[i]+'</small></button>').join('')+'</div>');$('#modal').querySelector('.dialog-close').remove();}
function manageBooks(){openModal('<h2>管理我的本子</h2><button class="button primary wide" data-action="create-book">＋ 新建手账本</button>'+state.books.map(b=>'<div class="book-manage-row"><strong>'+esc(b.title)+'</strong><button class="text-button" data-action="cover-book" data-id="'+b.id+'">换封面</button><button class="text-button" data-action="rename-book" data-id="'+b.id+'">改名</button><button class="text-button danger" data-action="delete-book" data-id="'+b.id+'">删除</button></div>').join('')+(state.deletedBooks.length?'<h3>收起的本子</h3>'+state.deletedBooks.map(b=>'<div class="book-manage-row"><span>'+esc(b.title)+'</span><button class="text-button" data-action="restore-book" data-id="'+b.id+'">恢复</button></div>').join(''):''));}

async function refreshExistingBorders(){const assets=[...state.records,state.draft].filter(Boolean).flatMap(d=>d.library);for(const a of assets){if(!a.base||a.borderVersion===9||borderType(a.border)==='none')continue;try{a.src=await whiteBorder(a.base,a.border);const image=await loadImage(a.src);a.ratio=image.height/image.width;a.borderVersion=9;}catch{}}persist();if(state.view==='home'||state.view==='book'||state.view==='calendar')render();}
